CREATE OR REPLACE FUNCTION nexus.taxonomy_coverage_counts_384(p_collection text) RETURNS TABLE(has_taxonomy boolean, chunks bigint, unassigned bigint) LANGUAGE sql STABLE AS $function$ WITH has_tax AS ( SELECT EXISTS ( SELECT 1 FROM nexus.taxonomy_centroids ct WHERE ct.collection = p_collection AND ct.embedding_384 IS NOT NULL ) AS v ), keyed AS ( -- the collection's chunks at this dimension SELECT c.tenant_id, c.chash, 1 AS is_chunk, 0 AS is_owned, 0 AS is_assigned FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_384 IS NOT NULL AND (SELECT v FROM has_tax) UNION ALL -- chunk_live_owners' predicate (vectors-018), read once for the collection: a manifest row whose document -- is not tombstoned SELECT m.tenant_id, m.chash, 0, 1, 0 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.collection = p_collection AND d.deleted_at IS NULL AND (SELECT v FROM has_tax) UNION ALL -- an assignment to a topic of this collection (projection rows onto other collections' topics do not count) SELECT ta.tenant_id, ta.doc_id, 0, 0, 1 FROM nexus.topic_assignments ta JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE t.collection = p_collection AND (SELECT v FROM has_tax) ), per_chash AS ( SELECT max(is_chunk) = 1 AS is_chunk, max(is_owned) = 1 AS is_owned, max(is_assigned) = 1 AS is_assigned FROM keyed GROUP BY tenant_id, chash ) SELECT (SELECT v FROM has_tax), count(*) FILTER (WHERE is_chunk AND is_owned), count(*) FILTER (WHERE is_chunk AND is_owned AND NOT is_assigned) FROM per_chash $function$;
